starter.css:
/* Register --track-color here */

.session-card {
  color: #1f2937;
  margin-block-end: 12px;
  padding: 12px 16px;
  border-inline-start: 6px solid var(--track-color, #64748b);
}
.session-card h2 { margin: 0 0 8px; font-size: 1.1rem; }
.badge {
  display: inline-block;
  padding: 0.1em 0.6em;
  border-radius: 999px;
  color: white;
  background: var(--track-color, #64748b);
}

.track-design { --track-color: #db2777; }
.track-perf { --track-color: #0891b2; }
/* Written by the CMS: someone typed a size into the color field */
.track-cms { --track-color: 12px; }

